        {
          "name": "address_line2",
          "comment": "地址行2(公寓)",
          "constraint": ""
        },
        {
          "name": "city",
          "comment": "城市",
          "constraint": ""
        },
        {
          "name": "state_province",
          "comment": "州/省",
          "constraint": ""
        },
        {
          "name": "postal_code",
          "comment": "邮政编码",
          "constraint": ""
        },
        {
          "name": "district",
          "comment": "区/町(亚洲地址预留)",
          "constraint": ""
        },
        {
