          "comment": "Google Place ID",
          "constraint": "UNIQUE"
        },
        {
          "name": "latitude",
          "comment": "纬度",
          "constraint": ""
        },
        {
          "name": "longitude",
          "comment": "经度",
          "constraint": ""
        },
        {
          "name": "verified",
          "comment": "是否已验证(V1.1预留)",
          "constraint": ""
        },
        {
          "name": "verified_at",
          "comment": "验证时间",
          "constraint": ""
        },
        {
          "name": "verified_source",
          "comment": "验证来源(google/usps/loqate)",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "核心实体，超集字段设计支持多国扩展"
    },
    {
      "name": "country_address_config",
      "comment": "国家地址配置",
      "columns": [
        {
          "name": "id",
          "comment": "主键 UUID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "country_code",
          "comment": "国家代码(引用market)",
          "constraint": "FOREIGN KEY, UNIQUE"
        },
        {
          "name": "enabled",
          "comment": "是否启用",
          "constraint": ""
        },
        {
          "name": "field_config",
          "comment": "字段配置(JSON: required_level/visible)",
          "constraint": ""
        },
        {
          "name": "field_order",
          "comment": "字段顺序(JSON)",
          "constraint": ""
        },
        {
          "name": "field_labels",
          "comment": "字段标签(JSON)",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
