          "constraint": "PRIMARY KEY"
        },
        {
          "name": "country_code",
          "comment": "国家代码",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "field_name",
          "comment": "字段名",
          "constraint": ""
        },
        {
          "name": "rule_type",
          "comment": "规则类型(pattern/length/custom)",
          "constraint": ""
        },
        {
          "name": "priority",
          "comment": "执行优先级(值小先执行)",
          "constraint": ""
        },
        {
          "name": "pattern",
          "comment": "正则表达式(pattern/custom时使用)",
          "constraint": ""
        },
        {
          "name": "min_length",
          "comment": "最小长度(length时使用)",
          "constraint": ""
        },
        {
          "name": "max_length",
          "comment": "最大长度(length时使用)",
          "constraint": ""
        },
        {
          "name": "error_message",
          "comment": "错误提示文案",
          "constraint": ""
        },
        {
          "name": "error_message_i18n_key",
          "comment": "多语言key(预留)",
          "constraint": ""
        },
        {
          "name": "enabled",
          "comment": "是否启用",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "纯技术校验(格式/长度)，按priority顺序执行。唯一约束: (country_code, field_name, rule_type)"
    },
    {
      "name": "administrative_division",
      "comment": "行政区划层级",
