          "constraint": ""
        },
        {
          "name": "code",
          "comment": "行政区划代码",
          "constraint": "UNIQUE"
        },
        {
          "name": "name",
          "comment": "名称",
          "constraint": ""
        },
        {
          "name": "name_local",
          "comment": "本地语言名称",
          "constraint": ""
        },
        {
          "name": "parent_id",
          "comment": "父级ID(自引用)",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "enabled",
          "comment": "是否启用",
          "constraint": ""
        },
        {
          "name": "sort_order",
          "comment": "排序权重",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "各国行政区划树形数据(州/市/区)，支撑下拉选择"
    },
    {
      "name": "postal_code_mapping",
      "comment": "邮编映射表",
      "columns": [
        {
          "name": "id",
          "comment": "主键 UUID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "country_code",
          "comment": "国家代码",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "postal_code",
          "comment": "邮政编码",
          "constraint": "UNIQUE"
        },
        {
          "name": "city",
          "comment": "城市",
          "constraint": ""
        },
        {
          "name": "state_code",
          "comment": "州/省代码",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
