    },
    {
      "name": "user",
      "comment": "用户(外部)",
      "columns": [
        {
          "name": "id",
          "comment": "用户ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "email",
          "comment": "邮箱",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "账户状态",
          "constraint": ""
        }
      ],
      "note": "用户模块提供，地址库引用user_id"
    },
    {
      "name": "country",
      "comment": "国家(market模块)",
      "columns": [
        {
          "name": "country_code",
          "comment": "ISO 3166-1 alpha-2",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "name",
          "comment": "国家名称",
          "constraint": ""
        },
        {
          "name": "enabled",
          "comment": "是否启用",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "货币代码",
          "constraint": ""
        }
      ],
      "note": "MARKET模块提供，地址库引用country_code"
    }
  ],
  "relations": [
    {
      "from": "user",
      "to": "address",
      "type": "1:N",
      "label": "拥有多个地址",
      "color": "#1565C0",
      "penwidth": 1.8
    },
    {
      "from": "country",
      "to": "address",
      "type": "1:N",
      "label": "地址所属国家",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "country_address_config",
      "type": "1:1",
      "label": "国家字段配置",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "address_field_validation_rules",
      "type": "1:N",
      "label": "校验规则(多规则)",
      "color": "#E8833A",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "postal_code_mapping",
      "type": "1:N",
      "label": "邮编数据",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "administrative_division",
      "type": "1:N",
      "label": "行政区划数据",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "administrative_division",
      "to": "administrative_division",
      "type": "1:N",
      "label": "父子层级(自引用)",
      "color": "#E8833A",
      "penwidth": 1.2,
      "style": "dashed"
    }
  ],
  "design_rules": {
    "superset_fields": "超集字段设计：数据库包含所有国家字段，通过country_address_config控制展示",
    "market_integration": "国家可用性引用market模块，地址库不独立维护国家列表",
    "frontend_i18n": "前端多语言采用i18n方案，数据库不存储多语言字段",
    "name_split": "recipient_first_name + recipient_last_name 拆分存储，支持支付AVS和物流API",
    "name_concat": "recipient_name 冗余存储拼接结果，拼接顺序由country_address_config.name_format控制",
    "address_type_enum": "address_type 枚举值: shipping, billing",
    "verified_source_enum": "verified_source 枚举值: google, usps, loqate",
    "soft_delete": "地址数据支持软删除(CCPA要求可彻底删除)",
    "encryption": "phone_number, recipient_first_name, recipient_last_name 字段 AES-256 加密存储",
    "place_id_dedup": "通过 place_id 做地址去重(V1.1)",
    "mvp_scope": "MVP只启用美国(US)，预留字段: alternate_phone_*, district, building_name, verified_*",
    "snapshot_ownership": "订单地址快照(order_address_snapshot)由订单模块管理，不在地址库ER图中体现",
    "backend_validation": "V1.2新增：address_field_validation_rules表存储后端校验规则，防止XSS/SQL注入/路径遍历攻击",
    "multi_rule_validation": "V1.3重构：同一字段支持多条校验规则，按priority顺序执行，命中首个失败即返回对应error_message",
    "rule_type_enum": "rule_type 枚举值: pattern(正则格式), length(长度范围), custom(自定义正则)。必填性不在此表",
    "required_level_ownership": "必填性(required/optional/hidden)由country_address_config.field_config统一管理，后端校验时先读config判断必填，再跑validation_rules的格式/长度规则",
    "field_config_structure": "field_config JSON结构: {field_name: {required_level: \"required\"|\"optional\"|\"hidden\", visible: bool}}"
  }
}
